file.change:

// WILD BLOCKER RENDER BRANCH
// Condition: cell.state === 'WILD'
//
// Visual spec:
//   Background: die face color (same as underlying cell.type color)
//   Center: large "F" character — font-mono font-black, ~60% of cell size
//   "F" color: face color darkened (e.g. amber-900 on amber-400 bg)
//   No pips rendered. No face number rendered.
//   Border ring: 2px white border + CSS animation hue-rotate(360deg) 2s linear infinite
//     Achieved via: className="animate-[hue-rotate_2s_linear_infinite]"
//     with ring-2 ring-white + filter: hue-rotate animation via inline style
//   Subject to gravity: normal pointer-events (can be chained)
//   Chain ring shows when isChained — same as normal die tile
//   Scale up on chain selection: same as normal die tile
//
// 3D die effect (applies to ALL die tiles including WILD):
//   box-shadow: inset -2px -3px 0px rgba(0,0,0,0.3), inset 2px 2px 0px rgba(255,255,255,0.15)
//   This gives a raised physical cube appearance without perspective transform
//   Selected state: box-shadow enhanced + translateY(-2px)
//
// AD BANNER SLOT (new optional prop):
//   showAdSlot?: boolean
//   onAdSlotClick?: () => void
//   When showAdSlot is true and cell.type === 'NONE' (empty):
//     Render a subtle "+" placeholder in the cell at 30% opacity
//     Clicking fires onAdSlotClick (rewarded ad trigger)
//     Only renders in SOLO modes — never in multiplayer
